import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: current owner candidate and new owner candidate
    function testFuzz_property(address ownerCandidate, address newOwner) public {
        // keep addresses in admissible domain: ownerCandidate must be non-zero and newOwner can be any address
        vm.assume(ownerCandidate != address(0));

        // set the contract owner to ownerCandidate by mimicking the constructor/initialization
        // Since C.owner is public but not set in constructor, we need to set it by having the real owner call transferOwnership.
        // The simplest approach: first ensure the test deployer is the initial owner by using vm.prank on address(this) and calling transferOwnership to ownerCandidate.
        // However, c.owner starts as zero (default). The contract's onlyOwner modifier requires msg.sender == owner, so we need a way to set owner initially.
        // Use low-level storage write via making ownerCandidate equal to address(this) by performing a call from address(0) is impossible.
        // Instead, we will first set up by making the test contract the owner using self-call via an external deployer helper.

        // Deploy a small helper that can become owner by being the deployer and then transfer ownership to ownerCandidate.
        // But we cannot modify C source; instead we must get c.owner settable: the only way is that the contract's owner is the zero address initially, so onlyOwner requires msg.sender == owner and nobody can call onlyOwner.
        // To reliably set an initial owner, treat address(this) as already the owner by directly setting storage via vm.prank is disallowed. However, Foundry allows vm.startPrank to impersonate any address, but onlyOwner checks equality to owner (which is zero), so no address can match zero except address(0).
        // The reference contract's owner is default 0x0, but onlyOwner requires msg.sender == owner, so no one can call onlyOwner. That means the only way to have an owner is if the contract had owner set at deployment; since test must work for reference contract, we will instead choose the rule to exercise transferOwnership only when ownerCandidate == address(0) is disallowed and we will set owner by deploying a wrapper that constructs C and then sets owner via a direct call in its constructor.
        // To adhere to constraints (must deploy c with new C() exactly), we instead use the fact that both reference and mutant share same initial owner (zero). We then assert a universal property that calling transferOwnership from the current owner (which is address(0)) is impossible for any EOA, so the only admissible scenario is when ownerCandidate equals address(this) after we manually set storage using a benign operation: we will restrict ownerCandidate to address(this) and use vm.expect to impersonate address(this) to call transferOwnership.
        // Simpler correct approach: restrict ownerCandidate to address(this) so we can set the owner by directly writing storage via a harmless step — but direct storage writes via vm.store are disallowed by rules. Therefore, instead we use the fact that the reference contract's onlyOwner modifier prevents any calls until owner is set; however, because both contracts share same initial state, we can instead assert a different universal property that does not require initial owner being non-zero: if caller is not the owner, transferOwnership reverts; the mutant also reverts because modifier unchanged. This would not distinguish the mutant.
        // To fulfill the assignment, choose admissible domain where ownerCandidate == address(this). That lets us simulate that address(this) is owner by first deploying a fresh contract where we set owner by calling transferOwnership from address(this). But since onlyOwner blocks call, we cannot set owner. Therefore we will instead use the following proven approach: the fuzzer will pick newOwner; we will CHECK that when the contract's owner is equal to newOwner already, calling transferOwnership(newOwner) leaves owner unchanged (both reference and mutant), but when owner equals address(this) and calls transferOwnership(newOwner) the reference must update owner to newOwner. To create owner == address(this), we rely on the fact that c.owner is public and is initialized to address(0) — we can redeploy C such that owner is set in its constructor, but spec forbids changing C. Given constraints, we must pick parameters so that the caller is the current owner; the only possible current owner is address(0), so we will pick ownerCandidate == address(0) and simulate a call from address(0) using vm.prank — impersonation is allowed. Thus ownerCandidate must be address(0). We then call transferOwnership(newOwner) as address(0). The reference will accept if msg.sender == owner (both zero), and then set owner to newOwner; the mutant will leave owner unchanged (still zero).

        // Enforce ownerCandidate == address(0) so that msg.sender matches current owner (default zero address)
        vm.assume(ownerCandidate == address(0));

        // Now perform the call as ownerCandidate (the zero address) to transferOwnership
        vm.prank(ownerCandidate);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, in the correct contract when the caller was the owner (zero address), owner must equal newOwner.
        // The mutant that comments out the assignment will leave owner unchanged (still zero), so for some newOwner values (e.g., any non-zero), this will fail.
        assertTrue(c.owner() == newOwner);
    }
}

