pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the original owner (who will perform the call) and the newOwner we want to transfer to
    function testFuzz_property(address ownerAddr, address newOwner) public {
        // admissible domain: ownerAddr must be non-zero (EOA) and newOwner must be non-zero
        vm.assume(ownerAddr != address(0));
        vm.assume(newOwner != address(0));

        // initialize contract owner to ownerAddr by impersonating and writing state via transferOwnership flow:
        // The contract's owner is zero by default; we need to set it to ownerAddr. Since transferOwnership is protected
        // by onlyOwner, we first set the contract's owner by directly poking the storage is not allowed.
        // Instead, we use the fact that C.owner is public but uninitialized; so we must deploy a fresh C and then
        // set its owner to ownerAddr by making ownerAddr the deployer: deploy through vm.prank.
        // However, setUp already deployed c with this test contract as deployer. To make ownerAddr the owner,
        // we call transferOwnership from the current owner (this test contract) to ownerAddr, then from ownerAddr
        // we will call transferOwnership to newOwner. That keeps fuzzing on ownerAddr and newOwner.

        // Step 1: current owner is this test contract (address(this)). Transfer ownership to ownerAddr.
        c.transferOwnership(ownerAddr);

        // Step 2: now ownerAddr should be owner; impersonate ownerAddr and call transferOwnership(newOwner).
        vm.prank(ownerAddr);
        c.transferOwnership(newOwner);

        // Single assertion: after a legitimate owner call to transferOwnership(newOwner), the contract's owner must equal newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

