// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: currentOwner (must be the deployer or an address we control) and a candidate newOwner
    function testFuzz_property(address initialOwner, address newOwner) public {
        // Keep addresses wide but avoid the zero-address for clarity (still admissible domain includes zero but owner may be zero)
        // We will make initialOwner the owner by having it call transferOwnership from the freshly deployed contract.
        // First, if initialOwner is zero, skip because pranking from address(0) isn't meaningful in foundry.
        vm.assume(initialOwner != address(0));

        // Make sure initialOwner has ETH to perform calls (prank uses an EOA)
        vm.deal(initialOwner, 1 ether);

        // By default the contract's owner is address(0) (uninitialized). We need to set owner to initialOwner.
        // Do this by having address(0) (the current owner) not able to call; instead, we first set owner to initialOwner by
        // using the deployer (address(this)) as current owner: but owner is currently address(0), and onlyOwner restricts calls.
        // To set a known owner, we exploit that the freshly deployed contract's owner is address(0). We cannot call transferOwnership
        // from address(0). So instead we directly initialize owner by deploying a new contract with owner set via transferOwnership pattern:
        // Simpler approach: use vm.startPrank(deployer) to set owner by directly calling transferOwnership only if deployer is current owner.
        // However initial contract's owner is address(0) so first make the contract's owner equal to address(this) by using low-level self-call
        // is not allowed. Instead, we will treat initialOwner as the current owner by: directly setting owner via calling transferOwnership from address(0) is impossible.
        // To get a valid scenario, we require that initialOwner equals address(this) (the test runner) or we first set owner to address(this) using the contract's transferOwnership
        // only if current owner is address(0) — but onlyOwner prevents that. Therefore we must instead initialize the contract owner via construction pattern.
        // To avoid changing contract C, we will handle admissible domain by requiring initialOwner == address(this) so we can call transferOwnership to assign newOwner.

